<template><PageShell title="Documents & Credentials" subtitle="Review organization application documents and ambulance credential dates in one place." icon="lucide:files" eyebrow="Organization Management"><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Documents" :value="stats.documents"/><Stat label="Approved" :value="stats.approved"/><Stat label="Pending" :value="stats.pending"/><Stat label="Credential alerts" :value="stats.credential_alerts"/></div><div class="mt-6 grid gap-6 xl:grid-cols-2"><section class="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]"><h2 class="font-black dark:text-white">Organization documents</h2><div class="mt-4 space-y-3"><article v-for="d in documents" :key="d.id" class="rounded-2xl bg-base-200 p-4"><div class="flex items-start justify-between gap-3"><div><p class="text-sm font-black dark:text-white/75">{{ pretty(d.doc_type) }}</p><p class="mt-1 text-xs text-slate-400">{{ d.original_name||'Submitted application file' }}</p></div><span class="rounded-full px-2.5 py-1 text-[.65rem] font-black" :class="d.status==='approved'?'bg-emerald-100 text-emerald-700':d.status==='rejected'?'bg-red-100 text-red-700':'bg-amber-100 text-amber-700'">{{ d.status }}</span></div><p v-if="d.rejection_reason" class="mt-2 text-xs text-red-600">{{ d.rejection_reason }}</p></article><p v-if="!documents.length" class="py-10 text-center text-sm text-slate-400">No organization documents recorded.</p></div></section><section class="rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]"><h2 class="font-black dark:text-white">Fleet credentials</h2><div class="mt-4 space-y-3"><article v-for="u in fleet" :key="u.id" class="rounded-2xl bg-base-200 p-4"><p class="text-sm font-black dark:text-white/75">{{ u.unit_code }} · {{ u.plate_number }}</p><div class="mt-2 grid grid-cols-2 gap-2 text-xs text-slate-500"><span>Registration<br><strong>{{ u.registration_expiry||'Not recorded' }}</strong></span><span>Inspection<br><strong>{{ u.inspection_expiry||'Not recorded' }}</strong></span></div><div v-if="u.credential_alerts?.length" class="mt-3 space-y-1"><p v-for="a in u.credential_alerts" :key="a.label" class="text-xs font-bold" :class="a.expired?'text-red-600':'text-amber-600'">{{ a.label }} {{ a.expired?'expired':'expires soon' }} · {{ a.date }}</p></div></article><p v-if="!fleet.length" class="py-10 text-center text-sm text-slate-400">No fleet credentials yet.</p></div></section></div></PageShell></template>
<script setup>import{defineComponent,h,onMounted,ref}from'vue';import PageShell from '@/components/management/PageShell.vue';import{fetchOrganizationDocuments}from'@/services/organizationCompletion';const documents=ref([]),fleet=ref([]),stats=ref({});const Stat=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('article',{class:'rounded-3xl border border-base-300 bg-base-100 p-5 shadow-sm dark:border-white/10 dark:bg-[#071829]'},[h('p',{class:'text-2xl font-black dark:text-white'},String(p.value??0)),h('p',{class:'mt-1 text-xs font-bold text-slate-500'},p.label)])});const pretty=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,m=>m.toUpperCase());onMounted(async()=>{const d=await fetchOrganizationDocuments();documents.value=d.documents||[];fleet.value=d.fleet_credentials||[];stats.value=d.stats||{}})</script>
